# 注释以 # 开头

# Server Block 基本格式
<zone>:[port] {
    <plugin> [arguments...]
    <plugin> {
        <option> <value>
    }
}

# 多Zone共享配置
<zone1> <zone2> <zone3>:[port] {
    <plugin>
}

# 1. 导入外部文件
import /etc/coredns/custom/*.conf

# 2. 环境变量替换
forward . {$UPSTREAM_DNS}

# 3. 多区域共享
cluster.local in-addr.arpa ip6.arpa:53 {
    kubernetes
}

# 4. 协议前缀
tls://.:853 {
    tls cert.pem key.pem ca.pem
    forward . 8.8.8.8
}

# 5. 通配符Zone
*.example.com:53 {
    forward . 10.0.0.1
}

# 多上游DNS服务器
forward . 8.8.8.8 8.8.4.4 1.1.1.1 {
    max_concurrent 1000
    max_fails 3
    health_check 5s
    policy round_robin
    expire 10s
}

# 基于域名分流
forward example.com 10.0.0.53 {
    max_concurrent 100
}

forward . /etc/resolv.conf {
    except example.com
    max_concurrent 1000
}

# 默认格式
log

# 自定义格式
log . "{remote}:{port} - [{time}] {>id} \"{type} {class} {name} {proto} {size}\" {rcode} {rsize} {duration}"

# 仅记录特定类型
log . {
    class denial    # 只记录否定响应
}

# 按域名过滤
log cluster.local {
    class all
}

.:53 {
    errors
    health

    # 重写ExternalName到实际CNAME
    rewrite continue {
        name regex (.*)\.external\.svc\.cluster\.local$ {1}.example.com
        answer name (.*)\.example\.com$ {1}.external.svc.cluster.local
    }

    kubernetes cluster.local in-addr.arpa ip6.arpa {
       pods insecure
       fallthrough in-addr.arpa ip6.arpa
    }

    forward . /etc/resolv.conf
    cache 30
    loop
    reload
    loadbalance
}

# DoT服务 (端口853)
tls://.:853 {
    tls /etc/coredns/cert.pem /etc/coredns/key.pem /etc/coredns/ca.pem

    errors
    health

    kubernetes cluster.local in-addr.arpa ip6.arpa {
       pods insecure
       fallthrough in-addr.arpa ip6.arpa
    }

    forward . tls://8.8.8.8 tls://8.8.4.4 {
        tls_servername dns.google
        health_check 5s
    }

    cache 30
    loop
    reload
    loadbalance
}

# 同时保留普通DNS (端口53)
.:53 {
    errors
    health

    kubernetes cluster.local in-addr.arpa ip6.arpa {
       pods insecure
       fallthrough in-addr.arpa ip6.arpa
    }

    forward . /etc/resolv.conf
    cache 30
    loop
    reload
    loadbalance
}

# 主集群配置
.:53 {
    errors
    health

    kubernetes cluster.local in-addr.arpa ip6.arpa {
       pods insecure
       fallthrough in-addr.arpa ip6.arpa
    }

    # 其他集群域名转发
    forward cluster-b.local 10.100.0.10 {
        max_concurrent 100
    }

    forward cluster-c.local 10.200.0.10 {
        max_concurrent 100
    }

    forward . /etc/resolv.conf
    cache 30
    loop
    reload
    loadbalance
}

.:53 {
    errors
    health

    # 对不存在的域名返回自定义响应
    template IN A blocked.domain.com {
        rcode NXDOMAIN
        authority "blocked.domain.com. 60 IN SOA ns.blocked.domain.com. admin.blocked.domain.com. 2021010100 3600 300 86400 60"
    }

    # 所有blocked子域返回0.0.0.0
    template IN A blocked {
        match .*\.blocked\.local$
        answer "{{ .Name }} 60 IN A 0.0.0.0"
        fallthrough
    }

    kubernetes cluster.local in-addr.arpa ip6.arpa {
       pods insecure
       fallthrough in-addr.arpa ip6.arpa
    }

    forward . /etc/resolv.conf
    cache 30
    loop
    reload
    loadbalance
}
